+  getMsgProperties(msgUri) {
     let properties = 0;
     try {
-      if (msgHdr) {
-        properties = msgHdr.getUint32Property("enigmail");
-
-        if (draft) {
-          if (self.getSavedDraftOptions(mimeMsg)) {
