+      // fail for URIs mutated in nsMailboxService::FetchMessage, and the
+      // "enigmail" property would not be present anyway.
+      if (
+        !(
+          /(^file:.*)/.test(msgUri) ||
+          /(^mailbox(-message)?:.*\?.*\bnumber=0(\D|$))/.test(msgUri)
