+      ) {
+        const msgHdr = gMessenger.msgHdrFromURI(msgUri);
+        if (msgHdr) {
+          properties = msgHdr.getUint32Property("enigmail");
         }
       }
     } catch (ex) {
-      console.error(ex);
+      console.warn(`Failure while getting msgHdr for URI ${msgUri}`, ex);
     }

     if (gEncryptedURIService.isEncrypted(msgUri)) {
